import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {createReadOnlyRpc,createMonitor,productionMonitor,formatRaw,GENESIS_RAW,ALLOCATIONS,COMMUNITY,MARKETING_TGE,MARKETING_RESERVE} from "../../transparency/monitor.mjs";
const token="0x"+"a".repeat(40),wallets=Array.from({length:9},(_,i)=>"0x"+String(i+1).padStart(40,"0")),hash="0x"+"b".repeat(64),tx="0x"+"c".repeat(64);
const manifest={chainId:8453,decimals:6,reviewed:true,runtimeCode:"0x6000",token,wallets};
const word=n=>"0x"+BigInt(n).toString(16).padStart(64,"0");
const block={number:"0x64",hash,timestamp:"0x6553f100"};
const log={address:token,removed:false,topics:["0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef","0x"+wallets[0].slice(2).padStart(64,"0"),"0x"+wallets[1].slice(2).padStart(64,"0")],transactionHash:tx,blockHash:hash,blockNumber:"0x64",logIndex:"0x0",data:word(1234567n)};
function fixture(overrides={}){
 const calls=[];const rpc=async(method,params)=>{calls.push([method,params]);if(Object.hasOwn(overrides,method))return typeof overrides[method]==="function"?overrides[method](params):overrides[method];switch(method){case "eth_chainId":return "0x2105";case "eth_getBlockByNumber":return block;case "eth_getCode":return "0x6000";case "eth_call":return params[0].data==="0x313ce567"?word(6n):params[0].data==="0x18160ddd"?word(GENESIS_RAW):word(1n);case "eth_getLogs":return [log,log];default:throw Error("unexpected RPC");}};return {rpc,calls};}
test("production is disabled and missing manifest makes no RPC calls",async()=>{const {rpc,calls}=fixture();const m=createMonitor({rpc});assert.equal((await m.snapshot()).status,"unavailable");assert.equal((await m.transfers({fromBlock:100n,toBlock:100n})).status,"unavailable");assert.equal(calls.length,0);assert.equal((await productionMonitor.snapshot()).data,null);});
test("exact raw policy conservation and public source consistency",()=>{assert.equal(ALLOCATIONS.reduce((a,b)=>a+b,0n),GENESIS_RAW);assert.equal(COMMUNITY.reduce((a,b)=>a+b,0n),ALLOCATIONS[0]);assert.equal(MARKETING_TGE,3111111108000n);assert.equal(MARKETING_RESERVE,59111111052000n);assert.equal(formatRaw(1234567n),"1.234567");const display=n=>{let [a,b]=formatRaw(n).split(".");return a.replace(/\B(?=(\d{3})+(?!\d))/g,",")+"."+b.replace(/0{0,4}$/,"");};for(const path of ["index.html","whitepaper/index.html","transparency/index.html","docs/WHITEPAPER.md"]){const page=readFileSync(new URL("../../"+path,import.meta.url),"utf8");for(const raw of [...ALLOCATIONS,...COMMUNITY,MARKETING_TGE,MARKETING_RESERVE])assert.ok(page.includes(display(raw)),path+" missing "+display(raw));}});
test("finalized pinned snapshot and cache, then explicit stale on provider failure",async()=>{let time=1000,fail=false;const {rpc,calls}=fixture({eth_chainId:()=>{if(fail)throw Error("429");return "0x2105";}});const m=createMonitor({manifest,rpc,now:()=>time,ttlMs:100});const x=await m.snapshot();assert.equal(x.status,"fresh");assert.equal(x.data.totalRaw,GENESIS_RAW.toString());assert.equal(x.data.finality,"finalized-provider-observed");assert.equal(Object.keys(x.data.balances).length,9);const n=calls.length;assert.equal((await m.snapshot()).status,"fresh");assert.equal(calls.length,n);time+=101;fail=true;assert.equal((await m.snapshot()).status,"stale");});
test("fail closed wrong chain, code, decimals, supply, duplicate custody and moving block",async()=>{for(const override of [{eth_chainId:"0x1"},{eth_getCode:"0x6001"},{eth_call:()=>word(7n)},{eth_call:p=>p[0].data==="0x313ce567"?word(6n):word(GENESIS_RAW+1n)},{eth_getBlockByNumber:p=>p[0]==="finalized"?block:{...block,hash:"0x"+"d".repeat(64)}}]){assert.equal((await createMonitor({manifest,...fixture(override)}).snapshot()).status,"unavailable");}assert.equal((await createMonitor({manifest:{...manifest,wallets:Array(9).fill(wallets[0])},...fixture()}).snapshot()).status,"unavailable");});
test("bounded finalized transfer page deduplicates and includes UTC source timestamp",async()=>{const m=createMonitor({manifest,...fixture()});const page=await m.transfers({fromBlock:100n,toBlock:100n});assert.equal(page.status,"fresh");assert.equal(page.data.rows.length,1);assert.equal(page.data.rows[0].amountRaw,"1234567");assert.equal(page.data.rows[0].timestamp,BigInt(block.timestamp).toString());assert.equal(page.data.nextFromBlock,null);assert.match(page.data.coverage,/not proof/);assert.equal((await m.transfers({fromBlock:100n,toBlock:101n})).status,"unavailable");assert.equal((await m.transfers({fromBlock:0n,toBlock:1000n})).status,"unavailable");});
test("malformed, conflicting or removed logs and RPC rate failures unavailable",async()=>{for(const logs of [[{...log,removed:true}],[log,{...log,data:word(2n)}],[{...log,blockHash:"0x"+"d".repeat(64)}],null])assert.equal((await createMonitor({manifest,...fixture({eth_getLogs:logs})}).transfers({fromBlock:100n,toBlock:100n})).status,"unavailable");assert.equal((await createMonitor({manifest,...fixture({eth_getLogs:()=>{throw Error("rate limited");}})}).transfers({fromBlock:100n,toBlock:100n})).status,"unavailable");});

test("cache snapshots cannot be modified by consumers and invalid limits fail closed",async()=>{const m=createMonitor({manifest,...fixture()});const a=await m.snapshot();a.data.balances[wallets[0]]="999";assert.equal((await m.snapshot()).data.balances[wallets[0]],"1");assert.equal((await createMonitor({manifest,...fixture(),maxBlocks:501n}).snapshot()).status,"unavailable");});
test("read-only HTTPS transport validates envelope and rejects write methods",async()=>{let calls=0;const rpc=createReadOnlyRpc({endpoint:"https://rpc.example.invalid/",fetchImpl:async(url,opts)=>{calls++;assert.equal(opts.redirect,"error");assert.equal(opts.credentials,"omit");const req=JSON.parse(opts.body);return new Response(JSON.stringify({jsonrpc:"2.0",id:req.id,result:"0x2105"}));}});assert.equal(await rpc("eth_chainId",[]),"0x2105");await assert.rejects(rpc("eth_sendRawTransaction",["0x00"]));assert.equal(calls,1);assert.throws(()=>createReadOnlyRpc({endpoint:"http://rpc.example.invalid/"}));assert.throws(()=>createReadOnlyRpc({endpoint:"https://rpc.example.invalid/?key=private"}));});
test("rate limiting opens cooldown without retries",async()=>{let now=100,calls=0;const rpc=createReadOnlyRpc({endpoint:"https://rpc.example.invalid/",now:()=>now,cooldownMs:1000,fetchImpl:async()=>{calls++;return new Response("",{status:429});}});await assert.rejects(rpc("eth_chainId",[]));await assert.rejects(rpc("eth_chainId",[]));assert.equal(calls,1);now+=1000;await assert.rejects(rpc("eth_chainId",[]));assert.equal(calls,2);});
test("mismatched IDs, oversized bodies, and aborted response are rejected",async()=>{for(const response of [new Response(JSON.stringify({jsonrpc:"2.0",id:99,result:"0x1"})),new Response("x".repeat(2048))]){const rpc=createReadOnlyRpc({endpoint:"https://rpc.example.invalid/",maxBytes:1024,fetchImpl:async()=>response});await assert.rejects(rpc("eth_chainId",[]));}const rpc=createReadOnlyRpc({endpoint:"https://rpc.example.invalid/",timeoutMs:10,fetchImpl:async(url,{signal})=>new Promise((resolve,reject)=>signal.addEventListener("abort",()=>reject(Error("aborted")),{once:true}))});await assert.rejects(rpc("eth_chainId",[]));});
